import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { DropdownModal } from './../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';

export type TextAlignmentDropdownProps = {
  dropdownOptions: {
    id: string;
    dataHook: string;
    label: string;
    icon: IconComponent;
    iconMobile: IconComponent;
  }[];
  onSelect: (value: string) => void;
  selectedId?: string;
  closeModal: () => void;
};

const TextAlignmentDropdown: React.FC<TextAlignmentDropdownProps> = ({
  dropdownOptions,
  onSelect,
  selectedId,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      options={dropdownOptions.map(
        ({ id: commandKey, dataHook, label, icon: Icon, iconMobile: IconMobile }) => (
          <ListItemSelect
            key={commandKey}
            dataHook={dataHook}
            prefix={isMobile && IconMobile ? <IconMobile /> : Icon ? <Icon /> : null}
            title={label}
            selected={commandKey === selectedId}
            onSelect={() => {
              onSelect(commandKey);
              closeModal();
            }}
          />
        )
      )}
      title={t('AlignTextDropdownButton_Tooltip')}
    />
  );
};

// oxlint-disable-next-line import/no-default-export
export default TextAlignmentDropdown;
