import { AlignBottom, AlignCenterHorizontally, AlignTop } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import type { VerticalAlignment } from './../../../../ricos-schema/next-schema/index.js';
import type { IToolbarItem } from './../../../../ricos-types/index.js';
import { DropdownButton } from './../../../../_shared/dropdown-button.js';

export const VERTICAL_ALIGNMENT_MODAL_ID = 'verticalAlignmentButton';

interface Props {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}

export const verticalAlignmentIcons = {
  TOP: AlignTop,
  MIDDLE: AlignCenterHorizontally,
  BOTTOM: AlignBottom,
} as const;

export const VerticalAlignmentButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(VERTICAL_ALIGNMENT_MODAL_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const verticalAlignment: VerticalAlignment = toolbarItem.attributes.verticalAlignment || 'TOP';
  const Icon = verticalAlignmentIcons[verticalAlignment as keyof typeof verticalAlignmentIcons];

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isModalOpen}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      ref={setReferenceElement}
      icon={Icon}
      tooltip={t('Toolbar_VerticalAlignment_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
